sp_widget.client_script:
api.controller = function() {
  var c = this;

  c.assetId = "";
  c.result = null;
  c.error = "";
  c.loading = false;

  c.data.studentName = c.data.studentName || "Campus Member";
  c.data.studentInitial = c.data.studentName.charAt(0).toUpperCase();

  c.search = function() {
    var value = (c.assetId || "").trim();

    if (!value || c.loading) return;

    c.loading = true;
    c.error = "";
    c.result = null;

    c.server.get({
      action: "find_asset",
      assetId: value
    }).then(function(response) {
      var data = response.data || {};

      if (data.result) {
        c.result = data.result;
      } else {
        c.error = data.error || "Check the Asset ID and try again.";
      }
    }, function() {
      c.error = "The lookup failed. Please try again.";
    }).finally(function() {
      c.loading = false;
    });
  };

  c.reset = function() {
    c.assetId = "";
    c.result = null;
    c.error = "";
  };
};

sp_widget.css:
.co-scan-page {
  color: #30234f;
  font-family: inherit;
}

.co-scan-page * {
  box-sizing: border-box;
}

.co-scan-page .co-app-layout {
  display: flex;
  align-items: stretch;
  gap: 20px;
  max-width: 1200px;
  min-height: 680px;
  margin: 0 auto;
  padding: 10px 0 25px;
}

/* Sidebar */
.co-scan-page .co-sidebar {
  position: sticky;
  top: 12px;
  align-self: flex-start;
  display: flex;
  flex-direction: column;
  flex-shrink: 0;
  width: 182px;
  min-height: 680px;
  padding: 16px 11px;
  border: 1px solid #e6dafa;
  border-radius: 22px;
  background: linear-gradient(180deg, #f7f2ff, #f1eaff);
}

.co-scan-page .co-brand {
  display: flex;
  align-items: center;
  gap: 9px;
  margin-bottom: 27px;
  padding: 3px 5px;
  color: #352451;
  font-size: 13px;
  font-weight: 800;
  text-decoration: none;
}

.co-scan-page .co-brand-mark {
  display: grid;
  place-items: center;
  flex-shrink: 0;
  width: 31px;
  height: 31px;
  border-radius: 11px;
  background: #8062c7;
  color: white;
  font-size: 17px;
}

.co-scan-page .co-brand small {
  display: block;
  margin-top: 3px;
  color: #8a7a9f;
  font-size: 9px;
  font-weight: 400;
}

.co-scan-page .co-nav-label {
  margin: 0 7px 9px;
  color: #9a88b9;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .9px;
}

.co-scan-page .co-nav-spaced {
  margin-top: 23px;
}

.co-scan-page .co-nav-item {
  display: flex;
  align-items: center;
  gap: 10px;
  min-height: 34px;
  margin-bottom: 3px;
  padding: 8px 10px;
  border-radius: 10px;
  color: #594574;
  font-size: 10px;
  text-decoration: none;
  transition: background .18s, transform .18s;
}

.co-scan-page .co-nav-item > span {
  width: 15px;
  color: #8062c7;
  text-align: center;
  font-size: 13px;
}

.co-scan-page .co-nav-item:hover,
.co-scan-page .co-nav-active {
  background: #e8defb;
  color: #563b92;
}

.co-scan-page .co-nav-item:hover {
  transform: translateX(2px);
}

.co-scan-page .co-sidebar-bottom {
  margin-top: auto;
  padding-top: 15px;
  border-top: 1px solid #e3d8f4;
}

.co-scan-page .co-sidebar-user {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 4px;
  min-width: 0;
}

.co-scan-page .co-avatar {
  display: grid;
  place-items: center;
  flex-shrink: 0;
  width: 29px;
  height: 29px;
  border-radius: 50%;
  background: #e5dafa;
  color: #6548a8;
  font-size: 11px;
  font-weight: 800;
}

.co-scan-page .co-user-copy {
  min-width: 0;
}

.co-scan-page .co-user-copy strong,
.co-scan-page .co-user-copy small {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.co-scan-page .co-user-copy strong {
  color: #493565;
  font-size: 9px;
}

.co-scan-page .co-user-copy small {
  margin-top: 4px;
  color: #9585ad;
  font-size: 9px;
}

/* Main page */
.co-scan-page .co-scan-main {
  flex: 1;
  min-width: 0;
  padding: 10px 0;
}

.co-scan-page .co-scan-page-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  margin: 3px 0 25px;
}

.co-scan-page .co-scan-breadcrumb {
  margin-bottom: 9px;
  color: #8a70bd;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 1px;
}

.co-scan-page .co-scan-page-header h1 {
  margin: 0 0 6px;
  color: #352451;
  font-size: clamp(23px, 2.5vw, 31px);
  font-weight: 800;
  letter-spacing: -.7px;
}

.co-scan-page .co-scan-page-header p {
  margin: 0;
  color: #8a7a9f;
  font-size: 11px;
}

.co-scan-page .co-scan-profile {
  flex-shrink: 0;
  padding: 10px 13px;
  border: 1px solid #e6dafa;
  border-radius: 10px;
  background: rgba(255,255,255,.7);
  color: #7051b8;
  font-size: 10px;
  text-decoration: none;
}

/* Scanner hero */
.co-scan-page .cas-hero {
  position: relative;
  overflow: hidden;
  padding: 35px 25px 27px;
  border: 1px solid #e5d7ff;
  border-radius: 23px;
  background: linear-gradient(135deg, #f0e8ff, #f9edff 55%, #fff1f7);
  text-align: center;
  box-shadow: 0 9px 28px rgba(87,61,135,.06);
}

.co-scan-page .cas-orb {
  position: absolute;
  width: 150px;
  height: 150px;
  border-radius: 50%;
  pointer-events: none;
}

.co-scan-page .cas-orb-one {
  top: -100px;
  left: -60px;
  background: rgba(178,153,245,.16);
}

.co-scan-page .cas-orb-two {
  right: -90px;
  bottom: -120px;
  background: rgba(244,178,218,.2);
}

.co-scan-page .cas-icon {
  position: relative;
  display: grid;
  place-items: center;
  width: 60px;
  height: 60px;
  margin: 0 auto 15px;
  border-radius: 20px;
  background: rgba(255,255,255,.8);
  color: #8062c7;
  box-shadow: 0 8px 22px rgba(91,64,145,.1);
}

.co-scan-page .cas-icon svg {
  width: 34px;
  height: 34px;
}

.co-scan-page .cas-eyebrow {
  display: block;
  color: #8a70bd;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 1.2px;
}

.co-scan-page .cas-hero h2 {
  position: relative;
  margin: 9px 0;
  color: #352451;
  font-size: 25px;
  font-weight: 800;
}

.co-scan-page .cas-hero > p {
  position: relative;
  max-width: 520px;
  margin: 0 auto;
  color: #796a96;
  font-size: 11px;
  line-height: 1.8;
}

.co-scan-page .cas-search {
  position: relative;
  display: flex;
  align-items: center;
  gap: 9px;
  max-width: 620px;
  margin: 23px auto 0;
  padding: 6px;
  border: 1px solid #e2d5fa;
  border-radius: 14px;
  background: rgba(255,255,255,.88);
  box-shadow: 0 7px 20px rgba(73,49,120,.06);
}

.co-scan-page .cas-search-icon {
  padding-left: 9px;
  color: #8062c7;
  font-size: 22px;
}

.co-scan-page .cas-search input {
  flex: 1;
  width: 100%;
  min-width: 0;
  height: 38px;
  border: 0;
  outline: none;
  background: transparent;
  color: #352451;
  font: inherit;
  font-size: 11px;
}

.co-scan-page .cas-search button,
.co-scan-page .cas-primary-link {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 38px;
  padding: 0 16px;
  border: 0;
  border-radius: 10px;
  background: #8062c7;
  color: white;
  font: inherit;
  font-size: 10px;
  font-weight: 700;
  text-decoration: none;
  cursor: pointer;
  transition: transform .2s, box-shadow .2s;
}

.co-scan-page .cas-search button:hover,
.co-scan-page .cas-primary-link:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 16px rgba(95,65,160,.2);
  color: white;
}

.co-scan-page .cas-search button:disabled {
  opacity: .55;
  cursor: not-allowed;
}

.co-scan-page .cas-hint {
  position: relative;
  margin-top: 15px;
  color: #8a7b9f;
  font-size: 10px;
}

.co-scan-page .cas-hint span {
  margin-right: 5px;
  color: #a080e4;
}

/* Search results */
.co-scan-page .cas-result,
.co-scan-page .cas-empty,
.co-scan-page .cas-feedback {
  margin-top: 17px;
  border: 1px solid #e7def5;
  border-radius: 19px;
  background: rgba(255,255,255,.85);
  box-shadow: 0 7px 22px rgba(66,45,105,.04);
}

.co-scan-page .cas-result {
  padding: 20px;
}

.co-scan-page .cas-result-top {
  display: flex;
  align-items: center;
  gap: 13px;
  padding-bottom: 17px;
  border-bottom: 1px solid #eee7f7;
}

.co-scan-page .cas-resource-icon {
  display: grid;
  place-items: center;
  flex-shrink: 0;
  width: 48px;
  height: 48px;
  border-radius: 14px;
  background: #f0e8ff;
  font-size: 22px;
}

.co-scan-page .cas-resource-heading {
  flex: 1;
  min-width: 0;
}

.co-scan-page .cas-resource-heading h2 {
  margin: 5px 0;
  font-size: 16px;
  overflow-wrap: anywhere;
}

.co-scan-page .cas-resource-heading p {
  margin: 0;
  color: #9484ad;
  font-size: 10px;
}

.co-scan-page .cas-status {
  padding: 6px 9px;
  border-radius: 30px;
  font-size: 9px;
  font-weight: 800;
  white-space: nowrap;
}

.co-scan-page .cas-status-available {
  background: #e4f7ee;
  color: #247a59;
}

.co-scan-page .cas-status-unavailable {
  background: #fff0d9;
  color: #96601a;
}

.co-scan-page .cas-status-other {
  background: #f0e8ff;
  color: #7051b8;
}

.co-scan-page .cas-result-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0,1fr));
  gap: 10px;
  padding: 17px 0;
}

.co-scan-page .cas-detail {
  padding: 12px;
  border: 1px solid #eee6fa;
  border-radius: 12px;
  background: #fcfaff;
}

.co-scan-page .cas-detail span {
  display: block;
  margin-bottom: 6px;
  color: #9585ae;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .5px;
}

.co-scan-page .cas-detail strong {
  color: #42315f;
  font-size: 11px;
  overflow-wrap: anywhere;
}

.co-scan-page .cas-result-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 9px;
}

.co-scan-page .cas-secondary-button {
  min-height: 38px;
  padding: 0 14px;
  border: 1px solid #e4d9f6;
  border-radius: 10px;
  background: white;
  color: #7051b8;
  font: inherit;
  font-size: 10px;
  cursor: pointer;
}

.co-scan-page .cas-secondary-button:hover {
  background: #f6f0ff;
}

.co-scan-page .cas-feedback {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 15px;
  border-color: #f2d3dc;
  background: #fff8fa;
}

.co-scan-page .cas-feedback-icon {
  display: grid;
  place-items: center;
  flex-shrink: 0;
  width: 28px;
  height: 28px;
  border-radius: 9px;
  background: #ffe7ed;
  color: #b44265;
  font-weight: 800;
}

.co-scan-page .cas-feedback strong {
  font-size: 12px;
}

.co-scan-page .cas-feedback p {
  margin: 5px 0 0;
  color: #866b7b;
  font-size: 11px;
  line-height: 1.6;
}

.co-scan-page .cas-empty {
  padding: 23px 16px;
  text-align: center;
}

.co-scan-page .cas-empty-icon {
  display: grid;
  place-items: center;
  width: 40px;
  height: 40px;
  margin: 0 auto 9px;
  border-radius: 14px;
  background: #f1eaff;
  color: #8062c7;
  font-size: 23px;
}

.co-scan-page .cas-empty h2 {
  margin: 0 0 8px;
  font-size: 14px;
}

.co-scan-page .cas-empty p {
  margin: 0 0 11px;
  color: #8b7ba2;
  font-size: 10px;
}

.co-scan-page .cas-empty a {
  color: #7051b8;
  font-size: 10px;
  font-weight: 700;
  text-decoration: none;
}

.co-scan-page .cas-footer {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  margin-top: 19px;
  padding: 13px 2px 0;
  border-top: 1px solid #e8e0f3;
  color: #9b8db0;
  font-size: 9px;
}

.co-scan-page .cas-footer > div:first-child strong {
  display: block;
  margin-bottom: 5px;
  color: #59417f;
}

.co-scan-page .cas-footer-links {
  display: flex;
  gap: 14px;
}

.co-scan-page .cas-footer-links a {
  color: #8062c7;
  text-decoration: none;
}

.co-scan-page .cas-footer-links a:hover {
  text-decoration: underline;
}

@media (max-width: 760px) {
  .co-scan-page .co-app-layout {
    flex-direction: column;
    gap: 14px;
    padding: 8px 0 20px;
  }

  .co-scan-page .co-sidebar {
    position: static;
    width: 100%;
    min-height: auto;
  }

  .co-scan-page .co-sidebar-bottom {
    margin-top: 15px;
  }

  .co-scan-page .co-scan-page-header {
    align-items: flex-start;
  }
}

@media (max-width: 480px) {
  .co-scan-page .cas-hero {
    padding: 25px 14px;
  }

  .co-scan-page .cas-search {
    gap: 4px;
  }

  .co-scan-page .cas-search button {
    padding: 0 10px;
  }

  .co-scan-page .cas-result-grid {
    grid-template-columns: 1fr;
  }

  .co-scan-page .cas-result-top {
    flex-wrap: wrap;
  }

  .co-scan-page .cas-footer {
    flex-direction: column;
  }
}

sp_widget.script:
(function() {
  data.studentName = gs.getUserDisplayName() || "Campus Member";
  data.studentInitial = data.studentName.charAt(0).toUpperCase();
  data.result = null;
  data.error = "";

  if (input && input.action === "find_asset") {
    var assetId = (input.assetId || "").trim();

    if (!assetId) {
      data.error = "Enter an Asset ID to search.";
      return;
    }

    var asset = new GlideRecord("u_campus_asset");
    asset.addQuery("u_asset_id", assetId);
    asset.setLimit(1);
    asset.query();

    if (!asset.next()) {
      data.error =
        "No asset matched that ID. Check the ID or browse the asset catalogue.";
      return;
    }

    var status = asset.getDisplayValue("u_status") || "Unknown";
    var statusLower = status.toLowerCase();
    var statusClass = statusLower === "available"
      ? "available"
      : (statusLower === "rented" ||
         statusLower === "borrowed" ||
         statusLower === "unavailable" ||
         statusLower === "maintenance"
          ? "unavailable"
          : "other");

    var type = asset.getDisplayValue("u_asset_type") || "";
    var typeLower = type.toLowerCase();
    var icon = "📦";

    if (typeLower.indexOf("book") > -1 ||
        typeLower.indexOf("text") > -1) {
      icon = "📚";
    } else if (typeLower.indexOf("laptop") > -1 ||
               typeLower.indexOf("computer") > -1) {
      icon = "💻";
    } else if (typeLower.indexOf("lab") > -1 ||
               typeLower.indexOf("equipment") > -1) {
      icon = "🧪";
    }

    data.result = {
      id: asset.getUniqueValue(),
      assetId: asset.getDisplayValue("u_asset_id"),
      name: asset.getDisplayValue("u_asset_name") || "Campus resource",
      type: type,
      status: status,
      statusClass: statusClass,
      location: asset.getDisplayValue("u_location") || "",
      condition: asset.getDisplayValue("u_condition") || "",
      maintenance: asset.getDisplayValue("u_maintenance_status") || "",
      icon: icon,
      detailsUrl: "/sp?id=asset_details&sys_id=" +
        asset.getUniqueValue()
    };
  }
})();
